+      name: 'SELECT does_not_exist',
+      status: 'error',
+      operation: 'SELECT',
+      text: 'SELECT * FROM does_not_exist',
+      collection: undefined,
+    },
+    {
+      name: 'DROP TABLE does_not_exist',
+      status: 'error',
+      operation: 'DROP',
+      text: 'DROP TABLE does_not_exist',
+      collection: undefined,
+    },
+    {
+      name: 'SELECT does_not_exist',
+      status: 'error',
+      operation: 'SELECT',
+      text: 'SELECT * FROM does_not_exist FORMAT JSONEachRow',
